#define N(a) ((int)(sizeof(a) / sizeof *(a)))
int bench_entry(void)
{
    int i;
    for (i = 0; i < N(d2); i++) { double a = D(d2[i].a), b = D(d2[i].b); ckd("d add", i, BD(a + b), d2[i].add); } done("rt binary64 add");
    for (i = 0; i < N(d2); i++) { double a = D(d2[i].a), b = D(d2[i].b); ckd("d sub", i, BD(a - b), d2[i].sub); } done("rt binary64 sub");
    for (i = 0; i < N(d2); i++) { double a = D(d2[i].a), b = D(d2[i].b); ckd("d mul", i, BD(a * b), d2[i].mul); } done("rt binary64 mul");
    for (i = 0; i < N(d2); i++) { double a = D(d2[i].a), b = D(d2[i].b); ckd("d div", i, BD(a / b), d2[i].div); } done("rt binary64 div");
    for (i = 0; i < N(dsq); i++) ckd("d sqrt", i, BD(sqrt(D(dsq[i].a))), dsq[i].r); done("rt binary64 sqrt (crt)");
    for (i = 0; i < N(d3); i++) { double a = D(d3[i].a), b = D(d3[i].b), c = D(d3[i].c); ckd("d a*b+c", i, BD(a * b + c), d3[i].r); } done("rt binary64 a*b+c");
    for (i = 0; i < N(f2); i++) { float a = F(f2[i].a), b = F(f2[i].b); ckf("f add", i, BF(a + b), f2[i].add); } done("rt binary32 add");
    for (i = 0; i < N(f2); i++) { float a = F(f2[i].a), b = F(f2[i].b); ckf("f sub", i, BF(a - b), f2[i].sub); } done("rt binary32 sub");
    for (i = 0; i < N(f2); i++) { float a = F(f2[i].a), b = F(f2[i].b); ckf("f mul", i, BF(a * b), f2[i].mul); } done("rt binary32 mul");
    for (i = 0; i < N(f2); i++) { float a = F(f2[i].a), b = F(f2[i].b); ckf("f div", i, BF(a / b), f2[i].div); } done("rt binary32 div");
    for (i = 0; i < N(fsq); i++) ckf("f sqrt", i, BF((float)sqrt(F(fsq[i].a))), fsq[i].r); done("rt binary32 sqrt (crt)");
    for (i = 0; i < N(f3); i++) { float a = F(f3[i].a), b = F(f3[i].b), c = F(f3[i].c); ckf("f a*b+c", i, BF(a * b + c), f3[i].r); } done("rt binary32 a*b+c");
    for (i = 0; i < N(ci); i++) { int64_t v = ci[i].i; ckd("i64->d", i, BD((double)v), ci[i].d); } done("rt int64->binary64");
    for (i = 0; i < N(ci); i++) { int64_t v = ci[i].i; ckf("i64->f", i, BF((float)v), ci[i].f); } done("rt int64->binary32");
    for (i = 0; i < N(cu); i++) { uint64_t v = cu[i].u; ckd("u64->d", i, BD((double)v), cu[i].d); } done("rt uint64->binary64");
    for (i = 0; i < N(cu); i++) { uint64_t v = cu[i].u; ckf("u64->f", i, BF((float)v), cu[i].f); } done("rt uint64->binary32");
    for (i = 0; i < N(cd); i++) { double v = D(cd[i].d); ckd("d->i64", i, (uint64_t)(int64_t)v, (uint64_t)cd[i].i); } done("rt binary64->int64");
    for (i = 0; i < N(cd); i++) { double v = D(cd[i].d); ckf("d->f", i, BF((float)v), cd[i].f); } done("rt binary64->binary32");
    for (i = 0; i < N(cdu); i++) { double v = D(cdu[i].d); ckd("d->u64", i, (uint64_t)v, cdu[i].u); } done("rt binary64->uint64");
    for (i = 0; i < N(kd_add); i++) ckd("K d add", i, BD(kd_add[i]), kd_add_x[i]); done("fold binary64 add");
    for (i = 0; i < N(kd_sub); i++) ckd("K d sub", i, BD(kd_sub[i]), kd_sub_x[i]); done("fold binary64 sub");
    for (i = 0; i < N(kd_mul); i++) ckd("K d mul", i, BD(kd_mul[i]), kd_mul_x[i]); done("fold binary64 mul");
    for (i = 0; i < N(kd_div); i++) ckd("K d div", i, BD(kd_div[i]), kd_div_x[i]); done("fold binary64 div");
    for (i = 0; i < N(kd_mac); i++) ckd("K d a*b+c", i, BD(kd_mac[i]), kd_mac_x[i]); done("fold binary64 a*b+c");
    for (i = 0; i < N(kf_add); i++) ckf("K f add", i, BF(kf_add[i]), kf_add_x[i]); done("fold binary32 add");
    for (i = 0; i < N(kf_sub); i++) ckf("K f sub", i, BF(kf_sub[i]), kf_sub_x[i]); done("fold binary32 sub");
    for (i = 0; i < N(kf_mul); i++) ckf("K f mul", i, BF(kf_mul[i]), kf_mul_x[i]); done("fold binary32 mul");
    for (i = 0; i < N(kf_div); i++) ckf("K f div", i, BF(kf_div[i]), kf_div_x[i]); done("fold binary32 div");
    for (i = 0; i < N(kf_mac); i++) ckf("K f a*b+c", i, BF(kf_mac[i]), kf_mac_x[i]); done("fold binary32 a*b+c");
    for (i = 0; i < N(kd_cu); i++) ckd("K u64->d", i, BD(kd_cu[i]), cu[i].d); done("fold uint64->binary64");
    for (i = 0; i < N(kf_cu); i++) ckf("K u64->f", i, BF(kf_cu[i]), cu[i].f); done("fold uint64->binary32");
    for (i = 0; i < N(kf_cd); i++) ckf("K d->f", i, BF(kf_cd[i]), cd[i].f); done("fold binary64->binary32");
    for (i = 0; i < N(lit_d); i++) ckd("lit d", i, BD(lit_d[i]), lit_d_x[i]); done("literal binary64");
    for (i = 0; i < N(lit_f); i++) ckf("lit f", i, BF(lit_f[i]), lit_f_x[i]); done("literal binary32");
    printf("TOTAL mismatches=%d\n", total);
    fflush(stdout);
    return total;
}
int main(void) { return bench_entry() != 0; }

